/* Налоговый калькулятор (макет 6:40886): вкладки монет, слева поля
   и промежуточные итоги, справа сумма налогов и годовые цифры. */
/* Оси «Тип лица в налогах» и «Резидентство» двигают ставку, а с ней —
   сумму налога, годовой итог и чистый доход */
const TAX_K=()=>({pf:1,ip:.92,ul:1.72}[S.taxface]??1)*(S.taxres==='no'?2.3:1);
const taxNum=v=>Number(String(v).replace(/\s/g,'').replace(',','.'));
const taxMul=(v,k)=>{const n=taxNum(v);return Number.isFinite(n)?ni(Math.round(n*k)):v};
const TAX_VALS=m=>{
  if(m.empty) return {inc:'0',rate:'4 647 685,61',kwt:'0',price:'0,00',eq:'0,00',life:'24',
    mon:'0,00',net:'0,00',year:'0,00',base:'0,00',el:'0,00',am:'0,00',c1:'0,00',c2:'0,00',c3:'0,00'};
  const k=TAX_K(), base={inc:'0.1',rate:'4 647 685,61',kwt:'140',price:'4',eq:'7 400 000',life:'24',
    mon:'39 270',net:'249 197',year:'471 241',base:'3 461 604',el:'4 838 400',am:'3 699 996',
    c1:'39 270',c2:'0,00',c3:'0,00'};
  if(k===1) return base;
  const dm=taxNum(base.mon)*(k-1);
  return {...base,mon:taxMul(base.mon,k),year:taxMul(base.year,k),c1:taxMul(base.c1,k),
    net:ni(Math.round(taxNum(base.net)-dm))};
};
V.tax=m=>{
  const v=TAX_VALS(m);
  const row=(l,x)=>`<div class="txrow"><span>${l}</span><b>${x} ₽</b></div>`;
  return `<div class="txtabs">${segLine('tax-coin',
    [`${COIN_ICON.BTC}BTC`,`${COIN_ICON.LTC}+ LTC`,`${COIN_ICON.ZEC}ZEC`],0)}</div>
  <div class="txwrap">
    <div class="txleft">
      <div class="txtop hr1">${seg('tax-form',['Физическое лицо и ИП','Юридическое лицо'],S.taxface==='ul'?1:0)}
        <div class="spacer"></div><button class="btn link creset" data-creset>Сбросить</button></div>
      <div class="txlist">
        <div class="txgroup"><span class="gk">Доходы</span>
          <div class="txrowin">${cfield('Доход*',v.inc)}${cfield('Курс на момент вывода, ₽*',v.rate)}</div></div>
        <div class="txgroup"><span class="gk">Расходы</span>
          <div class="txrowin">${cfield('Потребление, кВт·ч',v.kwt)}${cfield('Стоимость, ₽/кВт·ч (с НДС)',v.price)}
            ${cfield('Цена оборудования, ₽ (с НДС)',v.eq)}${cfield('Срок службы оборудования, мес.',v.life)}</div></div>
      </div>
    </div>
    <div class="txright">
      <div class="txchips">
        <span class="txchip">${COIN_ICON.BTC}≈ ${v.c1} ₽</span>
        <span class="txchip">${COIN_ICON.LTC}${COIN_ICON.DOGE}≈ ${v.c2} ₽</span>
        <span class="txchip">${COIN_ICON.ZEC}≈ ${v.c3} ₽</span>
      </div>
      <div class="txinfo">
        <span class="l">Сумма налогов за 1 мес.</span>
        <b class="mono">≈ ${v.mon} ₽</b>
        <span class="n">≈ ${v.net} ₽<i>Доход за вычетом налогов</i></span>
      </div>
      <div class="txrows">
        ${row('Сумма налогов за 1 год',v.year)}
        ${row('Налогооблагаемая база за 1 год',v.base)}
        ${row('Электроэнергия за 1 год',v.el)}
        ${row('Амортизация за 1 год',v.am)}
      </div>
    </div>
  </div>`;
};

