/* Строка, с которой открыли меню или QR; по умолчанию первая */
const obsCur=m=>{const r=obsOf(m); return r[U.obs??0]||r[0]||OBSERVERS[0]};
const OBS_REQ={acc:'Выберите хотя бы 1 аккаунт',perm:'Выберите хотя бы 1 разрешение',coin:'Выберите хотя бы 1 монету'};
function obsList(label,items,two,key){
  const on=i=>U.ochk.has(key+':'+i);
  const all=items.every((_,i)=>on(i));
  const err=U.oval&&!items.some((_,i)=>on(i));
  return `<div class="mlist ${err?'err':''}"><div class="ch"><span class="lb">${label}</span>
    <button class="btn link bs" data-ochkall="${key}:${items.length}">${all?'Снять все':'Выбрать все'}</button></div>
    <div class="opts ${two?'c2':''}">${items.map((t,i)=>
      `<label data-ochk="${key}:${i}">${cb(on(i))}${t.ico?`<span class="coins">${t.ico.map(c=>COIN_ICON[c]).join('')}</span>`:''}
        <span class="ell">${t.label??t}</span>${t.badge?`<span class="badge acc on">${t.badge}</span>`:''}</label>`).join('')}</div>
    ${err?`<div class="errmsg">${OBS_REQ[key]}</div>`:''}</div>`;
}
function obsForm(desc){
  /* аккаунты списком в две колонки, у основного — бейдж (макет 1393:165559) */
  const accs=SUBS.filter(x=>!x.arch).map(a=>({label:a.name,badge:a.main?'Основной':''}));
  return `<div class="mstack">
    ${prog(0,3)}
    ${(()=>{const e=U.oval?S.oerr:'no';
      const long=e==='long'?'Для четвертого менеджера с почти полным доступом к статистике аккаунта и всем монетам сразу, чтобы он мог следить':'';
      const val=e==='req'?'':(long||desc);
      const msg=e==='req'?'Поле обязательно для заполнения':e==='long'?'Максимум 100 символов':'';
      return `<div class="marea ${msg?'err':''}"><div class="box ${val?'':'dim'}">${val||'Описание'}</div>
        <div class="crow">${msg?`<span class="errmsg">${msg}</span>`:'<span></span>'}
          <span class="cnt2">${(val||'').length}/100</span></div></div>`})()}
    ${S.acct==='sub'
      ? `<div class="inp fl" style="margin:0"><span class="tx"><div class="k">Суб-аккаунт</div>
          <input value="alfred" readonly></span></div>`
      : obsList('Аккаунт',accs,true,'acc')}
    <div class="mlists">${obsList('Разрешения',OBS_PERMS,0,'perm')}${obsList('Монеты',OBS_COINS,0,'coin')}</div>
    ${(()=>{const i=segi('oterm',0);
      return `<div class="msel"><div class="lb">Срок действия</div>
      <span class="pop-wrap full" style="display:block">
        <button class="selbox full" data-pop="oterm">${OTERM[i][1]}<span class="spacer">${I.cd}</span></button>
        ${pop==='oterm'?`<div class="pop menu row up oterm">
          ${seg('oterm',OTERM.map(t=>t[0]),0)}
          ${datePicker([],3,2026,1).replace('class="pop dp"','class="dp"')}</div>`:''}
      </span></div>`})()}
  </div>`;
}
function obsTile(o,i){
  const url=LINKS.watcher(o.token);
  const tags=o.access.slice(0,2), rest=o.access.length-tags.length;
  return `<div class="tile2">
    <div class="row" style="margin-bottom:8px"><b style="font-size:var(--fs-b1);line-height:var(--lh-b1);font-weight:600">${o.name}</b>
      ${o.extra?`<span class="tag sm n">+${o.extra}</span>`:''}
      <span class="pop-wrap spacer"><button class="ibr dim" data-pop="obs${i}">${I.dots}</button>
      ${pop==='obs'+i?`<div class="pop menu">
        <button data-modal="obsedit">${I.edit}Редактировать</button>
        <div class="hr" style="margin:0"></div>
        <button class="del" data-modal="obsdel">${I.tr}Удалить</button></div>`:''}</span></div>
    <div class="row" style="gap:4px;margin-bottom:20px"><span class="coins">${o.coins.map(c=>COIN_ICON[c]).join('')}</span>
      <span class="bs semi ${o.off?'dim':''}">${o.off?'⦸ ':''}${o.label}</span></div>
    <div class="row" style="gap:4px;margin-bottom:20px;flex-wrap:wrap">
      ${tags.map(t=>`<span class="tag sm n">${t}</span>`).join('')}${rest>0?`<span class="tag sm n">+${rest}</span>`:''}</div>
    <div class="bs semi ${o.expired?'':'mut'}" style="margin-bottom:20px;${o.expired?'color:var(--neg)':''}">${o.term}</div>
    ${o.off?'':`<div class="row" style="gap:8px">
      <span class="linkfield" style="flex:1"><span class="mono">${url}</span>
        <button class="lnk spacer" style="color:var(--accent)" data-copy="${url}">${I.cp}</button></span>
      <button class="ib w" data-modal="qr">${I.qr}</button></div>`}
  </div>`;
}
/* Промо-баннеры внизу сводки — оба есть в макете */
const PROMOS=[['Снизили порог для<br>продажи ЦВ до 10 000 ₽','Продать',A+'banner-sell.png','assets'],
              ['Начните формировать свой<br>пассивный доход, став<br>партнером Promminer','Узнать больше',A+'banner-referral.png','ref']];
V.profile=m=>{
  const acct=S.acct==='main'?'natarusso':'alfred';
  const n=NOTIF_N[S.notif];
  /* в сводке показываются первые три — остальные за «Смотреть все» */
  const subs=subsOf(m).filter(x=>!x.arch), obs=obsOf(m).slice(0,3);
  const noname=S.name==='no';
  const notes=NOTES;
  return `<div class="grid cols2" style="grid-template-columns:1176fr 460fr;gap:var(--sp4);align-items:start">
  <div class="pcol">
    ${card(`<div class="ch"><h2>Мои суб-аккаунты</h2><button class="btn link spacer" data-go="subaccounts">Смотреть все</button></div>
      ${noname?`<div class="empty" style="padding:28px 0"><p style="max-width:372px">Чтобы начать добывать цифровую валюту необходимо добавить имя аккаунта</p>
        <button class="btn" style="margin-top:16px" data-modal="subacct">${I.pl} Добавить имя аккаунта</button></div>`
      :`<div class="grid g3" style="margin:0">${subs.map(s=>subTile(m,s)).join('')}
        ${S.role==='owner'&&subs.length<3?`<button class="dashed" style="grid-column:span ${3-subs.length}" data-modal="subacct">${I.pl}Создать суб-аккаунт</button>`:''}</div>`}`)}
    ${card(`<div class="ch"><h2>Мои наблюдатели</h2>${obs.length?'<button class="btn link spacer" data-go="observers">Смотреть все</button>':''}</div>
      ${obs.length?`<div class="grid g3" style="margin:0">${obs.map(obsTile).join('')}
        ${S.role==='owner'&&obs.length<3?`<button class="dashed" style="grid-column:span ${3-obs.length}" data-modal="observer">${I.pl}Создать ссылку наблюдателя</button>`:''}</div>`
      :`<div class="empty" style="padding:48px 0 40px"><div class="art">${I.eye}</div>
          <b>У вас еще нет созданных ссылок наблюдателей</b>
          ${S.role==='owner'&&!noname?`<button class="btn out sm" style="margin-top:16px" data-modal="observer">${I.pl} Создать</button>`:''}</div>`}`)}
    <div class="grid promos ${noname?'':'g2'}" style="margin:0">
      ${(noname?PROMOS.slice(1):PROMOS).map(([t,b,img,go],i)=>U.phide.has(noname?i+1:i)?'':`<section class="promo"><img class="art" src="${img}" alt="">
        <button class="pclose" data-phide="${noname?i+1:i}">${I.x}</button>
        <h2>${t}</h2><button class="btn" data-go="${go}">${b}</button></section>`).join('')}
    </div>
  </div>
  <div class="pcol">
    ${card(`<div class="ch"><h2>Мой профиль</h2></div>
      ${noname?`<div class="row" style="gap:var(--sp4);margin-bottom:20px"><span class="avat lg" style="width:64px;height:64px;font-size:var(--fs-h3);line-height:var(--lh-h3)">?</span>
        <button class="btn out sm" data-modal="subacct">${I.pl} Добавить имя аккаунта</button></div>`
      :`<div class="row" style="gap:var(--sp4);margin-bottom:20px"><span class="avat lg">${acct[0].toUpperCase()}</span>
        <span style="min-width:0"><span class="row" style="gap:2px"><b style="font-size:var(--fs-h5);line-height:var(--lh-h5);font-weight:600">${acct}</b>
          <button class="ibr" style="color:var(--accent)" data-copy="${acct}">${I.cp}</button></span>
          <div style="font-size:var(--fs-m);line-height:var(--lh-m);font-weight:600;color:var(--c3)">${FULLNAME}</div></span>
        <button class="ibr spacer dim" data-modal="personal">${I.edit}</button></div>
        <div class="hr" style="margin-top:0"></div>`}
      <button class="rowline" data-go="security"><span class="iconbox">${I.pc}</span>
        <span class="tx"><i>Последняя сессия</i><b class="row" style="gap:0;width:100%"><span class="ell">${SESSIONS[0].dev}</span><i class="pulse"></i></b></span>
        <span class="ch2 ibr">${I.cv}</span></button>
      ${noname?'':`<button class="rowline" data-go="security"><span class="iconbox">${GOOGLE}</span>
        <span class="tx"><b>Google Authentication</b><span class="badge">Не подключено</span></span>
        <span class="ch2 ibr">${I.cv}</span></button>`}`)}
    ${card(`<div class="ch"><h2>Последние уведомления</h2>${n?`<span class="cnt">${n>99?'99+':n}</span>`:''}
      <button class="btn link spacer dim" data-go="notifsettings">${I.cv}</button></div>
      ${n?`<div class="nplist">${notes.slice(0,Math.min(n,4)).map(([t,d,dt],i)=>`<div class="nitem" data-note="${i}"><i class="dot"></i>
          <div><div class="nb"><span class="nt">${t}</span><span class="nd">${dt}</span></div><p>${d}</p></div></div>`).join('')}</div>
        <div style="text-align:center;padding-top:8px"><button class="btn link" data-readall data-toast="Все уведомления отмечены как прочитанные">${I.checkall} Прочитать все</button></div>`
        :`<div class="empty" style="padding:96px 0"><b class="dim">Новых уведомлений нет</b></div>`}`)}
  </div>
</div>`;
};

/* ===== Верификация и реквизиты (страница 759:68419) =====
   Слева правовая форма и памятка, справа анкета и реквизиты.
   Светлый вариант макета — секция 778:17706, состояния и флоу — 2219:146235. */
const VFORMS=[['ip','Индивидуальный предприниматель'],['ur','Юридическое лицо'],['fiz','Физическое лицо']];
/* Ось «Правовая форма»: какой чип выбран при открытии анкеты */
const vformI=()=>({ip:0,ul:1,pf:2}[S.vform]??2);
/* Ось «Статус проверки»: плашка над анкетой */
const VSTAT={none:'',
  wait:`<div class="alert info" style="margin:0 0 16px">Анкета на проверке — обычно это занимает один рабочий день</div>`,
  ok:`<div class="alert ok" style="margin:0 0 16px">Данные проверены и приняты</div>`,
  err:`<div class="alert err" style="margin:0 0 16px">Данные отклонены: проверьте ИНН и код налоговой</div>`};
/* Поля анкеты по строкам: [подпись, значение, ключ ошибки] */
const FIO=[['Фамилия','Иванов'],['Имя','Иван'],['Отчество (необязательно)','Иванович']];
const TAXR=[['Код налоговой','123456','tax'],['ИНН','123456566788','inn']];
const VFIELDS={
  ip:[FIO,TAXR], fiz:[FIO,TAXR],
  ur:[[['Наименование организации','ООО «Руссо Майнинг»'],['Код налоговой','123456','tax']],
      [['ИНН','123456566788','inn'],['КПП','770701001']]]};
/* Ошибки полей — переключаются осью verr; у ИНН текст зависит от правовой формы
   (12 цифр у ИП и физлица, 10 у юрлица — макеты 2219:146974 и 2219:147107) */
const VERR={tax:()=>'Код налоговой должен содержать 4 цифры',
  inn:form=>`ИНН должен содержать ${form==='ur'?10:12} цифр`,
  bank:()=>'Поле обязательно для заполнения',
  file:()=>'Размер файла не может превышать 4 МБ'};
/* Памятка о правовых формах — блоки с синим заголовком (778:2677) */
const VHINTS=[
  ['Как физическое лицо вы можете:',
   ['Майнить цифровую валюту (ЦВ)','Выводить майнинговые и реферальные вознаграждения на кошельки','Не подавать отчет о майнинге']],
  ['Как ИП/юридическое лицо вы можете:',
   ['Майнить цифровую валюту (ЦВ)','Выводить майнинговые вознаграждения на кошельки',
    'Выводить реферальные вознаграждения на расчетный счет','Ежемесячно подавать отчеты о майнинге']]];
/* Поддержка — одни и те же контакты на экране и в модалке счета */
const VHELP=[['mail','Почта','poolsupport@promminer.ru','mailto:poolsupport@promminer.ru'],
  ['tg','Telegram','@PoolSupport','https://t.me/PoolSupport']];
const helpRow=([ic,k,v,u])=>`<a class="vhelp" href="${u}" target="_blank" rel="noopener">
  <span class="vhi">${I[ic]}</span><span class="k">${k}</span>
  <span class="spacer v">${v}${I.ext}</span></a>`;
/* Поле дизайн-системы: пока пусто — подпись служит плейсхолдером,
   при вводе и в заполненном виде она уезжает наверх (макет 2263:11095) */
const inpField=(label,val='',cls='')=>`<div class="inp fl ${cls}" style="margin:0">
  <span class="tx"><div class="k">${label}</div>
    <input placeholder="${label}" value="${val}"></span>
  <button class="vclear" data-clear>${I.x}</button></div>`;
/* Поле анкеты — то же поле плюс подпись ошибки */
const vField=([label,val,key],form)=>{
  const err=key&&S.verr===key, v=err?'12':(S.verif==='yes'?val:'');
  return `<div class="vfield">${inpField(label,v,err?'err':'')}
    ${err?`<div class="errmsg">${VERR[key](form)}</div>`:''}</div>`;
};
const bankLogo=(k,size=24)=>`<span class="blogo" style="width:${size}px;height:${size}px">${BANKS[k].svg}</span>`;
V.verification=m=>{
  /* Ось «Правовая форма» задаёт выбранный чип, пока его не трогали руками */
  const form=VFORMS[segi('vform',vformI())][0];
  const full=form!=='fiz';
  const doc=S.vdoc==='yes', acc=S.vacc==='yes';
  const head=(t,d)=>`<div class="vhead"><h2>${t}</h2><p>${d}</p></div>`;
  return `<div class="grid" style="grid-template-columns:460fr 1176fr;gap:var(--sp4);margin:0;align-items:start">
  <div class="vcol">
    ${card(`<div class="vform">
      <span class="vico">${I.uid}</span>
      <div class="vhead"><h2>Правовая форма</h2><p class="dim">Выберите правовую форму</p></div></div>
      <div class="vlist">${VFORMS.map(([,label],i)=>
        `<button class="chip ${i===segi('vform',vformI())?'on':''}" data-seg="vform" data-i="${i}" ${RO()}>${label}</button>`).join('')}</div>`)}
    <div class="vnote">${VHINTS.map(([t,list])=>`<div class="vnb"><b>${t}</b>
      <ul>${list.map(x=>`<li>${x}</li>`).join('')}</ul></div>`).join('')}</div>
  </div>
  <div class="vcol">
    ${card(`<h2 class="vh2">Верификация</h2>${VSTAT[S.vstat]||''}
      <div class="vrows">${VFIELDS[form].map(row=>
        `<div class="vrow" style="grid-template-columns:repeat(${row.length},1fr)">${row.map(f=>vField(f,form)).join('')}</div>`).join('')}</div>`)}
    ${full?card(`${head('Выписка из реестра майнеров','Добавьте, если хотите продавать намайненную цифровую валюту на нашей платформе')}
      ${doc?`<div class="vstate"><span class="vok">${I.ok}</span>Добавлена</div>`:''}
      <button class="btn ${doc?'g':''}" data-modal="vdocm" ${RO()}>${doc?'Изменить выписку':'Добавить выписку'}</button>`,'vsec'):''}
    ${full?card(`${head('Расчетный счет','Добавьте, если хотите выводить намайненную цифровую валюту в рублях')}
      ${acc?`<div class="vpay">${bankLogo('tbank',40)}
        <span class="tx"><i>Расчетный счет</i><b>12345678901234567890</b></span></div>`:''}
      <button class="btn ${acc?'g':''}" data-modal="vaccm" ${RO()}>${acc?'Изменить расчетный счет':'Добавить счет'}</button>
      <div class="vbanks"><p>Допустимые счета банков:</p>
        <div class="row" style="gap:20px;flex-wrap:wrap">${Object.keys(BANKS).map(k=>
          `<span class="vbank">${bankLogo(k)}${BANKS[k].short}</span>`).join('')}</div></div>`,'vsec')
      :''}
    ${full?card(`<h2 class="vh2">Помощь с открытием счета</h2>
      <div class="vrow" style="grid-template-columns:1fr 1fr">${VHELP.map(helpRow).join('')}</div>`):''}
  </div></div>`;
};

/* ===== Центр суб-аккаунтов (секция 1482:83256) =====
   Карточка с паддингом 8, внутри шапка 80 с паддингом 16 и таблица:
   две шапки (группы 32 и колонки 48) с чередующимися полосами,
   строки 74 и отдельная полоса «Все аккаунты» с радиусом 16. */
/* Состояния имени суб-аккаунта — ось saerr (кадры 1482:83893…1482:83968) */
const SA_RULES=['От 5 до 15 символов','Только строчные буквы (a−z) и цифры'];
const SA_VAL={ok:'larusso',short:'wR',caps:'wRfffffs',busy:'ivan',load:'larusso'};
const SA_BAD={short:[0,1],caps:[1]};
const SA_MSG={req:'Поле обязательно для заполнения',
  busy:'Данное имя суб-аккаунта уже используется в системе'};
const SUB_COLS=[
  ['Аккаунт','a',154],['Общий баланс','a',154],
  ['Активные','b',129],['Низкий хэш','b',129],['Отключены','b',129],['Оффлайн','b',129],
  ['BTC','a',93],['LTC','a',93],['ZEC','a',94],
  ['BTC','b',121],['LTC','b',121],['DOGE','b',121],['ZEC','b',121]];
const SUB_GROUPS=[['',2,'a'],['Воркеры',4,'b'],['Хэшрейт, 24 ч',3,'a'],['Доход',4,'b']];
V.subaccounts=m=>{
  /* Ось «Лимит суб-аккаунтов»: при исчерпанном лимите кнопка гаснет */
  const limit=S.sublim==='full';
  if(S.name==='no') return card(`<div class="ch subhead"><h2>Центр суб-аккаунтов</h2></div>
    <div class="subempty"><img src="${A}empty-subaccounts.png" alt="" width="210" height="167">
      <p>Чтобы начать добывать цифровую валюту<br>необходимо добавить имя аккаунта</p>
      <button class="btn" data-modal="subacct">Добавить имя аккаунта</button></div>`,'tblcard');
  /* колонки: 0 имя, 1 баланс, 2–5 воркеры, 6–8 хэшрейт, 9–12 доход */
  const rows=sortBy(subsOf(m),'subs',(r,k)=>{const i=+k.slice(1);
    return i===0?r.name:i===1?r.bal:i<6?r.w[i-2]:i<9?r.h[i-6]:r.inc[i-9]});
  const sum=i=>rows.reduce((a,r)=>a+r.w[i],0);
  const sumH=i=>rows.reduce((a,r)=>a+r.h[i],0);
  const sumI=i=>rows.reduce((a,r)=>a+r.inc[i],0);
  const HU=['TH/s','GH/s','KSol/s'], IC=['BTC','LTC','DOGE','ZEC'];
  const cells=r=>`<td class="mono">${nf(r.bal)} $</td>
    ${r.w.map(v=>`<td class="mono">${ni(v)}</td>`).join('')}
    ${r.h.map((v,i)=>`<td class="mono">${ni(v)} ${HU[i]}</td>`).join('')}
    ${r.inc.map((v,i)=>`<td class="mono">${dec(v)} ${IC[i]}</td>`).join('')}`;
  return card(`<div class="ch subhead"><h2>Центр суб-аккаунтов</h2><div class="spacer"></div>
  <label class="row" style="gap:12px;cursor:pointer"><span class="tog ${U.arch?'on':''}" data-arch></span>
    <span class="bs">Показать аккаунты в архиве</span></label>
  ${limit?`<span data-tip="Достигнут лимит суб-аккаунтов для вашего тарифа"><button class="btn" disabled>${I.pl} Добавить суб-аккаунт</button></span>`
    :`<button class="btn" data-modal="subacct" ${S.role==='observer'?'disabled':''}>${I.pl} Добавить суб-аккаунт</button>`}</div>
  <div class="tw"><table class="tbl subtbl">
  <thead>
    <tr class="grp">${SUB_GROUPS.map(([t,n,b])=>`<th class="b${b}" colspan="${n}">${t}</th>`).join('')}<th class="ba"></th></tr>
    <tr>${SUB_COLS.map(([t,b],i)=>{
      const ico=i>=9?`<span class="thico">${COIN_ICON[t]||''}</span>`:'';
      return sortTh('c'+i,ico+t,false,'b'+b,'subs')}).join('')}<th class="ba"></th></tr>
  </thead><tbody>
  ${rows.map(r=>`<tr><td><span class="subname"><b>${r.name}</b>
      <span class="badge acc ${r.main?'on':''}">${r.main?'Основной':'Суб-аккаунт'}</span></span></td>
    ${cells(r)}
    <td class="num">${r.main?'':`<button class="ibr dim"
      ${r.arch?'data-toast="Суб-аккаунт успешно активирован"':'data-modal="subarch"'}
      title="${r.arch?'Активировать':'Архивировать'}">${I.eyed}</button>`}</td></tr>`).join('')}
  </tbody>
  <tfoot><tr class="total"><td><b>Все аккаунты</b></td>
    <td class="mono">${nf(rows.reduce((a,r)=>a+r.bal,0))} $</td>
    ${[0,1,2,3].map(i=>`<td class="mono">${ni(sum(i))}</td>`).join('')}
    ${[0,1,2].map(i=>`<td class="mono">${ni(sumH(i))} ${HU[i]}</td>`).join('')}
    ${[0,1,2,3].map(i=>`<td class="mono">${dec(sumI(i))} ${IC[i]}</td>`).join('')}
    <td></td></tr></tfoot>
  </table></div>
  ${pager('subs',rows.length,20)}`,'tblcard')};

V.observers=m=>{
  const rows=obsOf(m);
  const head=`<div class="ch subhead"><h2>Мои наблюдатели</h2><div class="spacer"></div>
    <button class="btn" data-modal="observer" ${S.role==='observer'?'disabled':''}>${I.pl} Создать ссылку</button></div>`;
  const cols=['Аккаунт','Изменен','URL-адрес','Описание','Монеты','Разрешения','Срок действия'];
  const sel=U.osel, allSel=rows.length&&rows.every((_,i)=>sel.has(i));
  /* «Изменен» сортируется по дате, «Срок действия» — бессрочные в конец */
  const sorted=sortBy(rows,'obs',(o,k)=>k==='chg'
    ? o.changed.slice(6,10)+o.changed.slice(3,5)+o.changed.slice(0,2)+o.changed.slice(11)
    : (o.term==='Бессрочно'?'9999':o.term.replace(/\D/g,'')));
  if(S.name==='no') return card(`<div class="ch subhead"><h2>Мои наблюдатели</h2></div>
    <div class="subempty"><img src="${A}empty-subaccounts.png" alt="" width="210" height="167">
      <p>Чтобы начать добывать цифровую валюту<br>необходимо добавить имя аккаунта</p>
      <button class="btn" data-modal="subacct">Добавить имя аккаунта</button></div>`,'tblcard');
  if(!rows.length) return card(`${head}
    <div class="tw"><table class="tbl obstbl"><thead><tr>
      <th class="cbc">${cb(false)}</th>${cols.map(c=>`<th>${c}</th>`).join('')}<th></th>
    </tr></thead></table></div>
    <div class="subempty"><img src="${A}empty-subaccounts.png" alt="" width="210" height="167">
      <b>Наблюдателей пока нет</b>
      <p>У вас еще нет созданных ссылок<br>наблюдателей</p></div>`,'tblcard');
  return card(`${head}
  ${sel.size?`<div class="obulk"><b>Выбрано элементов: ${sel.size}</b><div class="spacer"></div>
    <button class="btn link" data-oselclear>Очистить выбор</button>
    <button class="btn danger sm" data-modal="obsdel">Удалить</button></div>`:''}
  <div class="tw"><table class="tbl obstbl">
  <thead><tr><th class="cbc">${cb(allSel,'data-oselall')}</th>
    <th>Аккаунт</th>${sortTh('chg','Изменен',0,'','obs')}<th>URL-адрес</th><th>Описание</th>
    <th>Монеты</th><th>Разрешения</th>${sortTh('term','Срок действия',0,'','obs')}<th></th></tr></thead>
  <tbody>${sorted.map((o,i)=>{const url=LINKS.watcher(o.token);
    const rest=o.access.length-1;
    return `<tr><td class="cbc">${cb(sel.has(i),'data-osel="'+i+'"')}</td>
    <td><span class="row" style="gap:8px"><span class="ell">${o.name}</span>
      ${o.extra?`<span class="chipn" data-tip="и ещё ${o.extra} ${o.extra===1?'аккаунт':'аккаунта'}">+${o.extra}</span>`:''}</span></td>
    <td class="mut">${o.changed}</td>
    <td class="mut"><span class="ell" style="max-width:180px;display:inline-block;vertical-align:middle">${url}</span></td>
    <td><span class="ell" style="max-width:180px;display:inline-block;vertical-align:middle">${o.label}</span></td>
    <td><span class="row" style="gap:4px">${o.coins.slice(0,2).map(c=>`<span class="coin1">${COIN_ICON[c]}${c}</span>`).join('')}
      ${o.coins.length>2?`<span class="chipn" data-tip="${o.coins.slice(2).join(', ')}">+${o.coins.length-2}</span>`:''}</span></td>
    <td><span class="row" style="gap:8px"><span class="ell">${o.access[0]}</span>
      ${rest>0?`<span class="chipn" data-tip="${o.access.slice(1).join(', ')}">+${rest}</span>`:''}</span></td>
    <td class="${o.expired?'neg':'mut'}">${o.term}</td>
    <td class="num"><span class="row" style="gap:4px;justify-content:flex-end">
      ${o.expired?'':`<button class="ibr acc" data-copy="${url}" title="Скопировать ссылку">${I.cp}</button>
      <button class="ibr acc" data-modal="qr" data-obs="${i}" title="QR-код">${I.qr}</button>`}
      <span class="pop-wrap"><button class="ibr" data-pop="ob${i}" title="Ещё">${I.dots}</button>
      ${pop==='ob'+i?`<div class="pop menu up">
        <button data-modal="obsedit" data-obs="${i}">${I.edit}Редактировать</button>
        <div class="hr" style="margin:0"></div>
        <button class="del" data-modal="obsdel" data-obs="${i}">${I.tr}Удалить</button></div>`:''}</span>
    </span></td></tr>`}).join('')}
  </tbody></table></div>
  ${pager('obs',rows.length,20)}`,'tblcard')};

/* Строка сессии: плашка 56, устройство с пульсом, IP • дата и город.
   У всех сессий, кроме текущей, справа кнопка завершения. */
const sessOut=s=>s.cur?'':`<button class="ibr spacer" data-modal="sessend" data-sess="${s.dev}"
  title="Завершить сессию">${I.login3}</button>`;
const sessRow=(s,act)=>secRow(I.monitor,
  `${s.dev}${s.act?'<i class="pulse"></i>':''}`,
  `<span class="sdots"><em>IP</em> ${s.ip}</span><span class="sdots">${s.when}</span><br>${s.loc}`,act??sessOut(s));
/* Группа сессий с капсовой подписью */
const sessGroup=(label,list,gray)=>list.length?`<div class="sgroup">
  <div class="scur ${gray?'off':''}">${label}</div>${list.map(x=>sessRow(x)).join('')}</div>`:'';
/* Безопасность (макет 971:102888): две карточки слева и «Сессии» справа.
   Строка секции — плашка 56, заголовок 16/20, подпись 14/18 и действие справа. */
const secRow=(ic,t,d,right)=>`<div class="srow"><span class="sico">${ic}</span>
  <span class="tx"><b>${t}</b><i>${d}</i></span>${right}</div>`;
/* Ось «Способ второго фактора»: приложение, SMS или письмо */
const FA_ICON=()=>S.fam==='sms'?I.phone:S.fam==='mail'?I.mail:GOOGLE;
const FA_NAME=()=>S.fam==='sms'?'Код в SMS':S.fam==='mail'?'Код на почту':'Google Authentication';
const FA_DESC=()=>S.fam==='sms'?'2FA через код из сообщения на телефон'
  :S.fam==='mail'?'2FA через код из письма на вашу почту'
  :'2FA через код из приложения Google';
V.security=m=>{
  const rows=sessOf(m), cur=rows[0], fa=S.fa==='yes';
  return `<div class="grid cols2" style="grid-template-columns:1176fr 460fr;align-items:start;gap:var(--sp4)">
  <div style="display:flex;flex-direction:column;gap:var(--sp4)">
    ${card(`<div class="stitle"><h2>Двухфакторная аутентификация</h2>
      <p>Защитите свой аккаунт, вывод средств, изменение настроек безопасности и подтверждение с помощью 2FA</p></div>
      ${secRow(FA_ICON(),FA_NAME(),FA_DESC(),
        `<span class="tog ${fa?'on':''} spacer ${RO()?'off':''}" ${RO()?'':`data-modal="${fa?'fa2off':'fa2on'}"`}></span>`)}`)}
    ${card(`<h2>Безопасность данных</h2>
      ${secRow(I.key,'Ваш пароль',S.pwdage==='old'
        ? 'Пароль не меняли больше года — самое время его обновить'
        : 'Этот пароль используется для входа в ваш аккаунт',
        `<button class="btn g sm spacer" data-modal="pwd" ${RO()}>Изменить</button>`)}
      ${S.del==='yes'
        ? secRow(I.tr2,'Удаление аккаунта',
            `Если передумали - напишите в <a class="acc" href="https://t.me/PoolSupport" target="_blank" rel="noopener">поддержку</a>`,
            '<span class="badge acc spacer">В процессе</span>')
        : secRow(I.tr2,'Удаление данных и аккаунта','Безвозратное удаление данных и всего, что связано с аккаунтом',
            `<button class="btn soft-danger sm spacer" data-modal="acctdel" ${RO()}>Удалить аккаунт</button>`)}`)}
  </div>
  <div>
    ${(()=>{const act=rows.filter(s=>!s.cur&&s.act).slice(0,4), more=rows.length>5;
      return card(`<div class="ch"><h2>Сессии</h2>${rows.length>1?'<button class="btn link spacer" data-modal="sessions">Все сессии</button>':''}</div>
      <div class="sgroup"><div class="scur">Это устройство</div>${sessRow(cur)}
        ${rows.length>1?`<button class="slink" data-modal="sessall">Завершить все сессии, кроме текущей</button>`:''}</div>
      ${act.length?`<div class="hr" style="margin:20px 0"></div>${sessGroup('Активные',act)}`:''}
      ${more?`<button class="btn g" style="width:100%;justify-content:center;margin-top:20px" data-modal="sessions">Показать все</button>`:''}`)})()}
  </div></div>`;
};

/* Список уведомлений — вкладка «Уведомления» в профиле (макет 2219:245853).
   Настройка каналов вынесена отдельным экраном за кнопкой «Настройка». */
