/* Попоувер уведомлений — по проду: заголовок + «Прочитать все», список,
   внизу кнопка «Посмотреть все» во всю ширину. */
function notifications(){
  const list=notesOf();
  const n=notifCount();
  return `<div class="pop wide">
    <div class="nhead"><b>Новые уведомления</b>${n?`<span class="cnt">${n>99?'99+':n}</span>`:''}
      <button class="ra ${n?'':'off'}" ${n?'data-readall data-toast="Все уведомления отмечены как прочитанные"':'disabled'}>${I.checkall}Прочитать все</button></div>
    ${n?`<div class="nplist">${list.slice(0,Math.min(n,5)).map(([t,d,dt],i)=>`<div class="nitem" data-note="${i}"><i class="dot"></i>
        <div><div class="nb"><span class="nt">${t}</span><span class="nd">${dt}</span></div><p>${d}</p></div></div>`).join('')}</div>`
      :`<div class="empty nempty"><img src="${A}empty-state.svg" alt="" width="120" height="95">
         <b class="dim">Уведомлений пока нет</b></div>`}
    <button class="btn xl" data-go="notifsettings">Посмотреть все</button></div>`;
}
/* Попоувер баланса — «Сводка по аккаунтам», как на проде */
/* Сводка по аккаунтам (макеты «Оболочки» 66:13325/13331/13337).
   Сводка и кнопка закреплены, прокручивается только список аккаунтов. */
const acctList=m=>{
  const base=subsOf(m);
  if(S.data!=='huge') return base;
  const extra=[];
  for(let i=1;i<=43;i++) extra.push({name:'account'+(20100+i),main:0,bal:485.45,h:[335,0,0]});
  return base.concat(extra);
};
function acctSummary(m){
  const cur=S.acct==='main'?'natarusso':'alfred';
  const rows=acctList(m);
  return `<div class="pop mid">
    <button class="acard asum" data-go="summary"><b class="t">Сводка по аккаунтам${I.arr}</b>
      <div class="kv">Общий баланс<span class="mono">${nf(rows.reduce((a,r)=>a+r.bal,0))} $</span></div>
      <div class="kv">Количество аккаунтов<span class="mono">${rows.length}</span></div></button>
    <div class="hr"></div>
    <div class="alist">${rows.map((r,i)=>`<div class="acard ${r.name===cur?'sel':''}" data-acct="${i===0?'main':'sub'}">
      <b class="t">${r.name}<span class="tag ${r.main?'sel':''} spacer">${r.main?'Основной':'Суб-аккаунт'}</span></b>
      <div class="kv">Общий баланс<span class="mono">${nf(r.bal)} $</span></div>
      <div class="kv">Хэшрейт, BTC<span class="mono">${ni(r.h[0])} TH/s</span></div>
      <div class="kv">Хэшрейт, LTC<span class="mono">${ni(r.h[1])} GH/s</span></div>
      <div class="kv">Хэшрейт, ZEC<span class="mono">${ni(r.h[2])} KSol/s</span></div></div>`).join('')}</div>
    <button class="btn out" style="width:100%;justify-content:center" data-modal="subacct">${I.pl} Добавить суб-аккаунт</button></div>`;
}



